import numpy as np,json
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
S=json.load(open('/app/output/spec.json'))
P=np.array(S['proprio']['position_m']); AX=np.array(S['proprio']['axis'])
C=np.array(S['cameras']['room_camera']['pose']['position_m'])
F=np.array(S['cameras']['room_camera']['pose']['forward']);F/=np.linalg.norm(F)
U=np.array(S['cameras']['room_camera']['pose']['up']);U/=np.linalg.norm(U)
R=np.cross(F,U);R/=np.linalg.norm(R)
f=128/np.tan(np.pi/8)
def project(p):
    d=np.asarray(p)-C
    return np.array([128+f*d@R/(d@F),128-f*d@U/(d@F)])
def unproject(uv,z):
    ray=F+(uv[0]-128)/f*R-(uv[1]-128)/f*U
    return C+(z-C[2])/ray[2]*ray
def tf(j,q):
    rot=Rotation.from_rotvec(AX[j]/np.linalg.norm(AX[j])*q).as_matrix()
    t=np.eye(4);t[:3,:3]=rot;t[:3,3]=P[j]-rot@P[j]
    return t
def fk(q,point,chain):
    T=np.eye(4)
    for j in chain:T=T@tf(j,q[j])
    return (T@np.r_[point,1])[:3]
def hand(q):return fk(q,[.329,.214,.097],[10,11,12,13,14])
def ik(target,q0):
    def err(a):
        q=q0.copy();q[11:15]=a
        return np.r_[(hand(q)-target)*10,(a-q0[11:15])*.015]
    ranges=np.array(S['action_types']['joint_position']['range_rad'])[11:15]
    res=least_squares(err,q0[11:15],bounds=(ranges[:,0],ranges[:,1]))
    q=q0.copy();q[11:15]=res.x
    return q,hand(q)
if __name__=='__main__':
    for z in [.75,.8,.85, .9,1.0]:
        print('plane',z,'boxbottom',unproject([118,153],z),'targetbottom',unproject([141,160],z))
    for z in [1,1.05]:
        for x in [[.0,0,z+.65],[.329,.214,z+.097],[0,0,z]]:print('project',x,project(x))
